#include "elf_loader.h"
static uint16_t le16(const uint8_t*p){return (uint16_t)p[0]|((uint16_t)p[1]<<8);} static uint32_t le32(const uint8_t*p){return (uint32_t)p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);} static uint64_t le64(const uint8_t*p){uint64_t v=0;for(uint32_t i=0;i<8u;++i)v|=(uint64_t)p[i]<<(8u*i);return v;}
int pros_elf64_validate(const uint8_t*b,uint64_t n,uint64_t*entry){if(!b||n<64u||!entry)return PROS_ELF_EINVAL;if(b[0]!=0x7f||b[1]!='E'||b[2]!='L'||b[3]!='F'||b[4]!=2u||b[5]!=1u)return PROS_ELF_ENOTSUP;if(le16(b+18)!=0x3eu)return PROS_ELF_ENOTSUP;uint64_t ph=le64(b+32);uint16_t ehsize=le16(b+52),entsz=le16(b+54),num=le16(b+56);if(ehsize!=64u||entsz!=56u)return PROS_ELF_EINVAL;if(ph>n||num>(n-ph)/entsz)return PROS_ELF_EBOUNDS;*entry=le64(b+24);for(uint16_t i=0;i<num;++i){const uint8_t*p=b+ph+(uint64_t)i*56u;if(le32(p)==1u){uint64_t off=le64(p+8),filesz=le64(p+32);if(off>n||filesz>n-off)return PROS_ELF_EBOUNDS;}}return PROS_ELF_OK;}
int pros_elf_selftest(void){uint8_t h[64]={0};uint64_t e=0;h[0]=0x7f;h[1]='E';h[2]='L';h[3]='F';h[4]=2;h[5]=1;h[18]=0x3e;h[54-16]=56;h[56]=0;if(pros_elf64_validate(h,sizeof(h),&e)!=PROS_ELF_OK)return -1;return 0;}
